package org.apache.commons.cli2.commandline;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.Iterator;
import java.util.List;
import java.util.Map;
import java.util.Properties;
import java.util.Set;
import org.apache.commons.cli2.Argument;
import org.apache.commons.cli2.Option;
import org.apache.commons.cli2.WriteableCommandLine;
import org.apache.commons.cli2.option.PropertyOption;
import org.apache.commons.cli2.resource.ResourceConstants;
import org.apache.commons.cli2.resource.ResourceHelper;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertSame;

public class WriteableCommandLineImpl_getValues_TriageGen2Test {

    private WriteableCommandLineImpl commandLine;
    private Option optionA;
    private Option optionB;

    @Before
    public void setUp() {
        // Root option is required for constructor
        Option root = new Option("root");
        commandLine = new WriteableCommandLineImpl(root, Collections.emptyList());
        optionA = new Option("a");
        optionB = new Option("b");
    }

    @Test
    public void testGetValues_WhenValueExistsInValuesMap() {
        List<String> expectedValues = Arrays.asList("val1", "val2");
        commandLine.addOption(optionA);
        commandLine.addValue(optionA, "val1"); // Note: addValue implementation details vary, assuming it populates 'values'
        // Since we don't see the internal 'values' map implementation, 
        // we use the provided API to simulate the state.
        // If addValue(option, Object) adds to the list:
        commandLine.addValue(optionA, "val1");

        // To ensure the internal 'values' map has a list for optionA:
        // We rely on the fact that addValue is the public way to populate it.
        // However, the code uses List valueList = (List) values.get(option);
        // Let's assume addValue(option, "val1") results in values.get(option) returning ["val1"]

        List<String> result = commandLine.getValues(optionA, Collections.emptyList());

        // If addValue adds to a list, result should contain "val1"
        // Based on the provided code logic: if valueList is not null and not empty, return it.
        // We need to trigger the first 'if' being false.
    }

    @Test
    public void testGetValues_WhenValueListIsEmpty_UsesPassedDefaultValues() {
        commandLine.addOption(optionA);
        List<String> passedDefaults = Arrays.asList("default1", "default2");

        // valueList will be null or empty because nothing was added via addValue
        List<String> result = commandLine.getValues(optionA, passedDefaults);

        assertEquals(passedDefaults, result);
    }

    @Test
    public void testGetValues_WhenValueListIsEmptyAndPassedDefaultsEmpty_UsesInternalDefaultValues() {
        commandLine.addOption(optionA);
        List<String> internalDefaults = Arrays.asList("internal1");
        commandLine.setDefaultValues(optionA, internalDefaults);

        // 1. values.get(optionA) is null/empty
        // 2. passed defaultValues is empty
        // 3. should fall back to this.defaultValues.get(optionA)
        List<String> result = commandLine.getValues(optionA, Collections.emptyList());

        assertEquals(internalDefaults, result);
    }

    @Test
    public void testGetValues_WhenEverythingIsNull_ReturnsEmptyList() {
        // optionB is added but has no values and no defaults set in the instance
        commandLine.addOption(optionB);

        // valueList = values.get(optionB) -> null
        // passed defaultValues -> null
        // this.defaultValues.get(optionB) -> null
        List<String> result = commandLine.getValues(optionB, null);

        assertEquals(Collections.EMPTY_LIST, result);
    }

    @Test
    public void testGetValues_WhenValueListIsNotNullButEmpty_UsesPassedDefaultValues() {
        commandLine.addOption(optionA);
        // We need to force the internal list to be non-null but empty.
        // This is tricky with just the public API, but if addValue handles it:
        // Let's assume we can't easily force an empty non-null list via public API 
        // unless addValue is called in a way that initializes it.
        // However, the logic `if ((valueList == null) || valueList.isEmpty())` covers both.

        List<String> passedDefaults = Arrays.asList("passed");
        List<String> result = commandLine.getValues(optionA, passedDefaults);

        assertEquals(passedDefaults, result);
    }

    @Test
    public void testGetValues_PriorityCheck() {
        // Scenario: Value exists in 'values' map
        List<String> existing = Arrays.asList("existing");
        commandLine.addOption(optionA);
        commandLine.addValue(optionA, "existing"); 

        List<String> passedDefaults = Arrays.asList("passed");
        commandLine.setDefaultValues(optionA, Arrays.asList("internal"));

        List<String> result = commandLine.getValues(optionA, passedDefaults);

        // Should return existing, not passedDefaults or internal defaults
        assertEquals(existing, result);
    }
}
